{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bupropion, the closest analogue sharing the 3-chlorophenyl and chiral methylamine motif, shows rapid BBB equilibration with a rat brain Kp,uu of 1.9, indicating active CNS uptake and meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Hydroxybupropion, another close analogue, also shows rapid BBB equilibration with a rat Kp,uu of 1.7, supporting CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A lipophilic amide-containing radiotracer, [18F]FNDP, exhibits high and rapid brain uptake in baboon PET imaging, demonstrating that neutral amide/aryl compounds of similar size can cross the BBB effectively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "An iodinated benzamide analogue shows significant accumulation in monkey brain, supporting the CNS permeability of benzamide-type structures related to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, neutral, moderately lipophilic diamide with a 3-chlorophenyl group and phenethylamine-like core. The closest experimental analogues, bupropion and hydroxybupropion, demonstrate Kp,uu values near 2 in rat microdialysis, indicating robust CNS access. Additional benzamide/amide radiotracer evidence supports brain penetration for this chemotype. Structural differences such as the absence of a basic amine and presence of two amides introduce some uncertainty, but the overall evidence favors meaningful CNS access.",
  "evidence_gaps": [
    "No direct Kp,uu, brain concentration, or CSF measurement exists for the query molecule itself.",
    "The closest analogues contain a basic amine/ketone rather than the query's neutral bis-amide, so transporter-mediated uptake seen for bupropion may not fully transfer.",
    "No explicit efflux transporter data for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

